import os
import collections
import re

def read_files(directory):
    files = []
    for file in os.listdir(directory):
        if file.endswith('.txt'):
            files.append(file)
    return files

def count_words(files):
    word_counts = collections.Counter()
    for file in files:
        with open(os.path.join(directory, file), 'r') as f:
            for line in f:
                words = re.findall(r'\b\w+\b', line.lower())
                for word in words:
                    word_counts[word] += 1
    return word_counts

def top_5_words(word_counts):
    return word_counts.most_common(5)

directory = 'path/to/directory'
files = read_files(directory)
word_counts = count_words(files)
top_5_words = top_5_words(word_counts)
print(top_5_words)
```

This program first reads all the text files under the specified directory. It then counts the occurrences of each word in each file. Finally, it returns the top-5 words with the most occurrences.

Please replace 'path/to/directory' with the actual path to the directory you want to read.<|end_turn|>

